  ui_story_30780101_56_dialog_content = "Kalau ban pelampung berdiameter 4 meter itu... Ketika kau memakainya, orang tidak akan bisa mendekat dengan jarak kurang dari 2 meter saat berbicara denganmu.",
  ui_story_30780101_57_dialog_content = "Ah, tentu saja... Ini memang barang-barang yang kamu suka, Robyn...",
  ui_story_30780101_58_dialog_content = "Tapi sepertinya bukan hadiah yang cocok untuk Dayna, walaupun kamu suka...",
  ui_story_30780101_59_dialog_content = "Berarti betul, 'kan? Aku... Aku tidak pandai memilih hadiah yang bagus...",
  ui_story_30780101_60_dialog_content = "J-jangan sedih. Bagaimana kalau kita menerapkan bagian pertama pepatah itu untuk memilih hadiah?",
  ui_story_30780101_61_dialog_content = "Bagian pertama?",
  ui_story_30780101_62_dialog_content = "Ya. Bagian tentang menghadiahi orang barang yang dia suka.",
  ui_story_30780101_63_dialog_content = "Jadi, ayo kita pilihkan hadiah yang Dayna akan suka.",
  ui_story_30780101_64_dialog_content = "Satu-satunya hal yang Dayna akan suka... adalah <color=#FFB400>Eclipsite yang membunuh orang tua kami</color>.",
  ui_story_30780101_65_dialog_content = "Kamu yakin itu yang dia suka?",
  ui_story_30780101_66_dialog_content = "Tentu saja. Kalau aku bisa memberinya Eclipsite itu supaya dia bisa menyayat perut dan mengulitinya...",
  ui_story_30780101_67_dialog_content = "Mencincang, mengiris, dan mencacahnya...",
  ui_story_30780101_68_dialog_content = "Aku yakin dia akan tersenyum puas saat mengirisnya.",
  ui_story_30780101_69_dialog_content = "Bagaimana bisa kamu mengatakan itu tanpa menunjukkan emosi?",
  ui_story_30780101_70_dialog_content = "Lagi pula, apa Dayna benar-benar akan tersenyum puas...",
  ui_story_30780101_71_dialog_content = "Tapi... Aku tidak bisa menemukan Eclipsite itu, jadi tidak bisa menghadiahkannya...",
  ui_story_30780101_72_dialog_content = "Nah, selain Eclipsite itu, ada lagi yang dia suka?",
  ui_story_30780101_73_dialog_content = "Yang lain? Kalau begitu, pasti <color=#FFB400>aku</color>.",
  ui_story_30780101_74_dialog_content = "Kamu?!",
  ui_story_30780101_75_dialog_content = "Oh, aku paham. Aku akan memberikan diriku sendiri sebagai hadiah!",
  ui_story_30780101_76_dialog_content = "A-apa?! Bagaimana kamu bisa menyimpulkan begitu?!",
  ui_story_30780101_77_dialog_content = "Aku akan masuk ke kotak hadiah besar, mengikatkan pita, dan menunggunya di depan pintu...",
  ui_story_30780101_78_dialog_content = "Wow, wow, wow! Itu terlalu aneh!",
  ui_story_30780101_79_dialog_content = "Aku paham kalian tidak ingin terpisahkan, tapi bukannya itu malah akan membuatnya takut?",
  ui_story_30780101_80_dialog_content = "Kalau begitu... Aku harus bagaimana?",
  ui_story_30780101_81_dialog_content = "Pasti ada banyak cara agar dua orang tidak terpisahkan.",
  ui_story_30780101_82_dialog_content = "Bagaimana kalau...",
  ui_story_30780101_83_option_content = "Memberinya sesuatu yang akan membuatnya merasa lebih dekat denganmu?",
  ui_story_30780101_84_dialog_content = "Lebih dekat denganku?",
  ui_story_30780101_85_dialog_content = "Ya. Sesuatu seperti...",
  ui_story_30780101_86_dialog_content = "Seperti... Karet panjang?",
  ui_story_30780101_87_dialog_content = "Apa? Kenapa karet panjang?",
  ui_story_30780101_88_dialog_content = "Karet panjang bisa dipakai untuk mengikat Dayna dan aku.",
  ui_story_30780101_89_dialog_content = "Kalau aku berjalan terlalu jauh dari Dayna, karet panjang itu akan menarikku kembali kepadanya.",
  ui_story_30780101_90_dialog_content = "Dengan begitu, kami akan lebih dekat satu sama lain.",
  ui_story_30780101_91_dialog_content = "(Astaga... Aku tidak paham caranya berpikir...)",
  ui_story_30780101_92_dialog_content = "(Yang kupikirkan tadi adalah pakaian atau aksesori yang berpasangan...)",
  ui_story_30780101_93_option_content = "Cobalah memberinya sesuatu yang membuatnya ingin bekerja sama?",
  ui_story_30780101_94_dialog_content = "Mendorong kami bekerja sama?",
  ui_story_30780101_95_dialog_content = "Ya. Sesuatu seperti...",
  ui_story_30780101_96_dialog_content = "Bom waktu yang kabel merah dan birunya terhubung?",
  ui_story_30780101_97_dialog_content = "Apa? Kenapa bom waktu?",
  ui_story_30780101_98_dialog_content = "Kalau bom waktu, Dayna dan aku harus memotong kabel merah dan biru secara bersamaan untuk menjinakkannya.",
  ui_story_30780101_99_dialog_content = "Kalau bom waktu dengan kabel merah dan biru terhubung, Dayna dan aku harus memotong kabel-kabel ini bersamaan untuk menjinakkannya.",
  ui_story_30780101_100_dialog_content = "Itu jelas akan mendorong kami bekerja sama.",
  ui_story_30780101_101_dialog_content = "(Astaga... Aku tidak paham caranya berpikir...)",
  ui_story_30780101_102_dialog_content = "(Aku tadi akan menyarankan permainan papan untuk dimainkan bersama...)",
  ui_story_30780101_103_dialog_content = "PlayerName, menurutmu bagaimana dengan ini sebagai hadiah?",
  ui_story_30780101_104_dialog_content = "Menurutku, ini kurang pas sebagai hadiah...",
  ui_story_30780101_105_dialog_content = "Benarkah? Aku tahu aku...",
  ui_story_30780101_106_dialog_content = "J-jangan bersedih... A-ayo kita coba cari yang lain.",
  ui_story_30780101_107_dialog_content = "Jangan pikirkan apa yang Dayna suka... Kita beri saja <color=#FFB400>barang yang dia perlu</color>.",
  ui_story_30780101_108_dialog_content = "Misalnya, sepertinya dia suka memakai setelan bersih. Bagaimana kalau kita beri dia sikat lembut untuk merawat setelannya?",
  ui_story_30780101_109_dialog_content = "Hmm? Sepertinya Dayna akan perlu itu...",
  ui_story_30780101_110_dialog_content = "Tapi dia sudah punya peralatan lengkap untuk merawat setelannya. Menurutku dia tidak butuh sikat lagi.",
  ui_story_30780101_111_dialog_content = "Coba kupikir... Barang lain yang Dayna butuhkan...",
  ui_story_30780101_112_dialog_content = "Aku tahu! Dia membutuhkan <color=#FFB400>perlengkapan medis portabel</color>!",
  ui_story_30780101_113_dialog_content = "Perlengkapan medis?",
  ui_story_30780101_114_dialog_content = "Betul. Terkadang Dayna menjalankan misi tanpa aku.",
  ui_story_30780101_115_dialog_content = "Dia selalu terluka saat kembali, dan setelannya pasti berantakan.",
  ui_story_30780101_116_dialog_content = "Aku tidak tahu kenapa dia begitu, tapi aku selalu khawatir...",
  ui_story_30780101_117_dialog_content = "Kalau aku memberinya perlengkapan medis portabel, dia akan lebih terawat saat menjalankan misi tanpa aku.",
  ui_story_30780101_118_dialog_content = "Bagaimanapun, kami sudah setuju untuk bersama-sama mencari Eclipsite yang membunuh orang tua kami.",
  ui_story_30780101_119_dialog_content = "Kalau membawa perlengkapan medis portabel, setidaknya dia akan bisa mencegah lukanya mengotori setelannya sebelum bertemu Eclipsite itu...",
  ui_story_30780101_120_dialog_content = "Kedengarannya bagus... Dibandingkan dengan saranmu sebelumnya, Robyn, ide ini bagus sekali sampai-sampai aku tidak percaya ini berasal darimu...",
  ui_story_30780101_121_dialog_content = "Kalau begitu, beri dia hadiah itu.",
  ui_story_30780101_122_dialog_content = "Terima kasih, PlayerName. Tanpamu, aku tidak akan pernah terpikir hadiah sebagus ini untuknya.",
  ui_story_30780101_123_dialog_content = "Aku harus <color=#FFB400>memberimu hadiah juga</color> sebagai balas budi.",
  ui_story_30780101_124_dialog_content = "<size=45>?!</size>",
  ui_story_30780101_125_dialog_content = "<size=45>T-tidak, tidak, jangan...!!</size>",
  ui_story_30780601_1_dialog_content = "(Fiuh, ini seharusnya pekerjaan terakhir...)",
  ui_story_30780601_2_dialog_content = "(Ini seharusnya tempatnya, kan?)",
  ui_story_30780601_3_dialog_content = "<color=#e8d9bb>Ding—Dong—</color>",
  ui_story_30780601_4_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_30780601_5_dialog_content = "Halo, tolong mundur dan jaga jarak aman dariku. Jika tidak, akibatnya akan sangat buruk...",
  ui_story_30780601_6_dialog_content = "B-baiklah!",
  ui_story_30780601_7_dialog_content = "Ah... Itu kamu, PlayerName...",
  ui_story_30780601_8_dialog_content = "Maafkan saya, saya pikir Anda adalah seorang penjual atau orang yang mengganggu lainnya, yang datang dari pintu ke pintu... Anda bisa santai sekarang.",
  ui_story_30780601_9_dialog_content = "Eh, baiklah...",
  ui_story_30780601_10_dialog_content = "Aku membawa buku-buku yang kamu minta, Robyn.",
  ui_story_30780601_11_dialog_content = "Jika tidak ada yang lain, saya harus pergi—",
  ui_story_30780601_12_dialog_content = "...",
  ui_story_30780601_13_dialog_content = "Ada apa?",
  ui_story_30780601_14_dialog_content = "Masih ada satu bagian terakhir dari permintaanku...",
  ui_story_30780601_15_dialog_content = "Hah? Apakah aku lupa sesuatu?",
  ui_story_30780601_16_dialog_content = "Hmm... Aku butuh kamu memberikan ringkasan singkat dari setiap buku ini, PlayerName.",
  ui_story_30780601_17_dialog_content = "Aku mencoba mengajak Dayna membaca buku bersamaku...",
  ui_story_30780601_18_dialog_content = "Tapi dia tidak pernah cukup tenang untuk membaca apa pun.",
  ui_story_30780601_19_dialog_content = "Juga, sebagian besar buku ini tentang tempat-tempat dari seluruh dunia.",
  ui_story_30780601_20_dialog_content = "Jadi, saya pikir seorang pelancong seperti Anda mungkin bisa membantu. Apakah itu tidak masalah, PlayerName?",
  ui_story_30780601_21_dialog_content = "Begitu. Itu seharusnya tidak menjadi masalah. Lagipula, pekerjaanku hari ini sudah selesai.",
  ui_story_30780601_22_dialog_content = "Lalu... Masuklah.",
  ui_story_30780601_23_dialog_content = "Hah? Kau langsung membiarkanku masuk ke rumahmu?",
  ui_story_30780601_24_dialog_content = "Ya... Aku sudah merapikan semuanya. Aku yakin kamu akan merasa nyaman di sini.",
  ui_story_30780601_25_dialog_content = "Aku yakin aku juga akan, tapi... tidakkah jarak ini akan mengganggumu?",
  ui_story_30780601_26_dialog_content = "Jangan khawatir... Itu tidak terlalu mengganggu saya di rumah sendiri.",
  ui_story_30780601_27_dialog_content = "Selain itu, kita sudah saling kenal cukup lama, PlayerName... Itu seharusnya bukan masalah.",
  ui_story_30780601_28_dialog_content = "Coba... Jangan membuat gerakan mendadak, ya...",
  ui_story_30780601_29_dialog_content = "Oke, aku akan mencoba untuk berhati-hati...",
  ui_story_30780601_30_dialog_content = "Aku masuk ya.",
  ui_story_30780601_31_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_30780601_32_dialog_content = "Sedikit kecil... Silakan duduk di mana pun... Maaf tidak menyiapkan apa-apa sebelumnya...",
  ui_story_30780601_33_dialog_content = "Tidak apa-apa. Mungkin tidak banyak ruang di sini, tapi rasanya benar-benar nyaman.",
  ui_story_30780601_34_dialog_content = "Hangat dan nyaman, bahkan...",
  ui_story_30780601_35_dialog_content = "Ada yang salah?",
  ui_story_30780601_36_dialog_content = "Tidak, tapi saya harus mengatakan... Pakaianmu terlihat sangat spesial hari ini, Robyn!",
  ui_story_30780601_37_dialog_content = "Aku biasanya tidak bisa melihatmu seperti ini...",
  ui_story_30780601_38_dialog_content = "...",
  ui_story_30780601_39_dialog_content = "... Aku tahu aku seharusnya tidak membiarkanmu masuk. Jika itu terlalu mengganggumu, kamu selalu bisa pergi.",
  ui_story_30780601_40_dialog_content = "I-Itu bukan maksudku sama sekali! Yang ingin kukatakan adalah pakaian itu terlihat sangat bagus padamu!",
  ui_story_30780601_41_dialog_content = "Ini seperti angin segar dibandingkan dengan pakaian hitam total yang biasa kamu kenakan!",
  ui_story_30780601_42_dialog_content = "...",
  ui_story_30780601_43_dialog_content = "(Sungguh sulit untuk mengetahui apa yang sedang Robyn pikirkan saat ini...)",
  ui_story_30780601_44_dialog_content = "(Andai saja dia mau menurunkan penjagaannya sesekali... Saya hanya berharap dia tidak salah paham padaku.)",
  ui_story_30780601_45_dialog_content = "Benarkah? T-Terima kasih atas pujianmu, PlayerName...",
  ui_story_30780601_46_dialog_content = "(Fiuh... Syukurlah dia mengerti.)",
  ui_story_30780601_47_dialog_content = "Saya tidak sering berinteraksi dengan orang seperti ini, jadi saya tidak tahu... kesan apa yang akan saya buat...",
  ui_story_30780601_48_dialog_content = "Kurasa itu sangat cocok denganmu.",
  ui_story_30780601_49_dialog_content = "A... Aku sudah paham. Tak perlu mengulanginya lagi...",
  ui_story_30780601_50_dialog_content = "Aku akan membuat teh untuk kita... Bagaimana kalau kamu duduk di tempat tidur untuk sekarang, PlayerName?",
  ui_story_30780601_51_dialog_content = "Uh, apakah benar-baik saja jika aku duduk di sana?",
  ui_story_30780601_52_dialog_content = "Orang jarang datang ke sini, jadi... Saya tidak pernah repot-repot membeli furnitur untuk tamu.",
  ui_story_30780601_53_dialog_content = "Jadi, silakan duduk di atas kasur. Jika Dayna di sini, dia bahkan akan melemparkan dirinya ke atasnya...",
  ui_story_30780601_54_dialog_content = "Eh... Yah, kalau kamu bersikeras.",
  ui_story_30780601_55_dialog_content = "Teh Anda sudah siap... Saya akan letakkan di sini.",
  ui_story_30780601_56_dialog_content = "Terima kasih. Nanti aku makan sedikit.",
  ui_story_30780601_57_dialog_content = "Saya akan mulai membaca sekarang. Jika saya kesulitan memahami sesuatu—",
  ui_story_30780601_58_dialog_content = "Kamu akan menjelaskannya padaku, kan?",
  ui_story_30780601_59_dialog_content = "Tentu. Sementara itu, aku akan mencari hal lain untuk dibaca.",
  ui_story_30780601_60_dialog_content = "Oke.",
  ui_story_30780601_61_dialog_content = "...",
  ui_story_30780601_62_dialog_content = "(Sunyi sekali... Suara satu-satunya adalah suara halaman yang berbalik.)",
  ui_story_30780601_63_dialog_content = "(Jadi ini adalah bagaimana Robyn terlihat ketika dia tenggelam dalam bacaannya...)",
  ui_story_30780601_64_dialog_content = "(Tempat tidurnya sangat empuk, dan sinar matahari sore yang sangat menyenangkan...)",
  ui_story_30780601_65_dialog_content = "*menguap*",
  ui_story_30780601_66_dialog_content = "Merasa mengantuk, PlayerName?",
  ui_story_30780601_67_dialog_content = "Ah... Tidak, aku baik-baik saja. Hanya saja, di sini sangat nyaman.",
  ui_story_30780601_68_dialog_content = "Sebenarnya... Sudah lama aku tidak merasa sesantai ini.",
  ui_story_30780601_69_dialog_content = "Lalu... Apakah kamu ingin tidur siang?",
  ui_story_30780601_70_dialog_content = "Hah?",
  ui_story_30780601_71_dialog_content = "Jangan khawatir... Aku baru saja mencuci dan mengeringkan kasur hari ini...",
  ui_story_30780601_72_dialog_content = "Bukan itu yang aku khawatirkan! Tempat tidurmu jauh lebih bersih daripada milikku, Robyn!",
  ui_story_30780601_73_dialog_content = "Bukan hanya itu... Ada aroma lembut dan menyenangkan yang berasal dari seprai.",
  ui_story_30780601_74_dialog_content = "Yah, memang saya menggunakan deterjen baru yang populer untuk mencucinya tadi.",
  ui_story_30780601_75_dialog_content = "Mereka bilang aroma ini seharusnya memiliki khasiat penyembuhan, jadi aku ingin mencobanya...",
  ui_story_30780601_76_dialog_content = "Bagaimana kabarmu, PlayerName?",
  ui_story_30780601_77_option_content = "Rasanya benar-benar nyaman.",
  ui_story_30780601_78_dialog_content = "Kehangatan kamar Anda hanya menambah perasaan itu juga.",
  ui_story_30780601_79_dialog_content = "Sangat menenangkan di sini.",
  ui_story_30780601_80_dialog_content = "Sangat santai... sampai-sampai semakin sulit untuk tetap terjaga...",
  ui_story_30780601_81_option_content = "Rasanya benar-benar istimewa.",
  ui_story_30780601_82_dialog_content = "Produk paling populer di Umbraton selalu begitu unik.",
  ui_story_30780601_83_dialog_content = "Ini sangat cocok untuk kamarmu, Robyn.",
  ui_story_30780601_84_dialog_content = "Sejujurnya, hanya berada di sini saja membuatku merasa sedikit pusing...",
  ui_story_30780601_85_dialog_content = "Ah... Itu bukan hal istimewa, sungguh.",
  ui_story_30780601_86_dialog_content = "Saya membeli barang-barang seperti ini dari waktu ke waktu... Tapi saya selalu khawatir... bahwa mereka akan terbuang sia-sia.",
  ui_story_30780601_87_dialog_content = "Jadi... Terima kasih telah berbagi pikiranmu denganku, PlayerName.",
  ui_story_30780601_88_dialog_content = "Kamu pasti lelah setelah melakukan perjalanan sejauh ini hanya untuk mengantarkan beberapa buku... Benar?",
  ui_story_30780601_89_dialog_content = "J-Jika kamu tidak keberatan... Tolong... Silakan istirahat sebentar.",
  ui_story_30780601_90_dialog_content = "B-Baiklah, kalau begitu... Aku akan pejamkan mataku sebentar.",
  ui_story_30780601_91_dialog_content = "<color=#e8d9bb>Berdebar-</color>",
  ui_story_30780601_92_dialog_content = "(Sangat nyaman sekali...)",
  ui_story_30780601_93_dialog_content = "(Robyn masih membaca... Dia tampak seperti kutu buku sekarang...)",
  ui_story_30780601_94_dialog_content = "(Kelopak mataku... Mulai terasa sangat berat...)",
  ui_story_30780601_95_dialog_content = "<color=#e8d9bb>Di hangatnya sinar matahari sore, tidur siang sebentar bisa dengan mudah berlangsung selama berjam-jam...</color>",
  ui_story_30780601_96_dialog_content = "Zzzz... Zzzz... Hmm?",
  ui_story_30780601_97_dialog_content = "(Oh tidak, aku tertidur! Berapa lama aku tertidur?)",
  ui_story_30780601_98_dialog_content = "(Ini buruk, seharusnya aku menceritakan lebih banyak tentang buku-buku ini kepada Robyn! Semoga dia tidak terlalu...)",
  ui_story_30780601_99_dialog_content = "Zzzz... Zzzz...",
  ui_story_30780601_100_dialog_content = "Ah... Dia juga sedang tidur?",
  ui_story_30780601_101_dialog_content = "Matahari sedikit terlalu terang sekarang. Aku harus menutup gorden untuk Robyn.",
  ui_story_30780601_102_dialog_content = "Tetapi... aku khawatir aku mungkin akan membangunkannya.",
  ui_story_30780601_103_dialog_content = "Aku harus melangkah melewati dia dan meraih meja kerjanya untuk menutupnya.",
  ui_story_30780601_104_dialog_content = "Ini tidak akan mudah, tapi saya harus mencoba!",
  ui_story_30780601_105_dialog_content = "Zzzz... Hmm?",
  ui_story_30780601_106_dialog_content = "Ah, maaf... Apakah aku membangunkanmu?",
  ui_story_30780601_107_dialog_content = "Hmm... Tidak... Tidak juga...",
  ui_story_30780601_108_dialog_content = "Aku... bangun sendiri.",
  ui_story_30780601_109_dialog_content = "Mimpinya juga sangat indah... Aku terus mengingatkan diri sendiri bahwa aku tidak bisa tidur selamanya...",
  ui_story_30780601_110_dialog_content = "Benarkah? Tentang apa itu, Robyn?",
  ui_story_30780601_111_dialog_content = "Aku bermimpi tentang langit dan laut, tentang gunung dan hutan... dan kita. Aku bermimpi bahwa kita sedang terbang melewatinya semua.",
  ui_story_30780601_112_dialog_content = "\"Kita\"?",
  ui_story_30780601_113_dialog_content = "Benar, PlayerName, kamu dan aku...",
  ui_story_30780601_114_dialog_content = "Kami melayang di angin seperti bulu... dan mengapung di ombak lautan...",
  ui_story_30780601_115_dialog_content = "Mendengarkan suara jangkrik di hutan... dan berlari melintasi kolam teratai setelah hujan...",
  ui_story_30780601_116_dialog_content = "Terdengar seperti mimpi yang indah...",
  ui_story_30780601_117_dialog_content = "Aku cukup yakin ini ada hubungannya dengan buku yang sedang kubaca...",
  ui_story_30780601_118_dialog_content = "Ada sesuatu yang benar-benar magis tentang prosa dan puisi naratif...",
  ui_story_30780601_119_dialog_content = "Ada beberapa puisi dari Longzhou... Meskipun saya tidak bisa sepenuhnya memahami maknanya, saya cukup mengerti untuk merasakan keindahan seninya.",
  ui_story_30780601_120_dialog_content = "Apakah kamu ingin membaca beberapa buku bersamaku, PlayerName?",
  ui_story_30780601_121_dialog_content = "Uh... Tentu, tapi aku bukan ahli dalam hal ini... Mungkin interpretasiku juga kurang akurat.",
  ui_story_30780601_122_dialog_content = "Jika itu bukan masalah bagi kamu, maka saya akan senang membaca beberapa puisi bersamamu.",
  ui_story_30780601_123_dialog_content = "Sama sekali tidak... Di sini, aku akan berbagi tempat dudukku denganmu.",
  ui_story_30780601_124_dialog_content = "Baiklah, tapi apakah kamu yakin tentang ini? Kita akan duduk sangat dekat satu sama lain...",
  ui_story_30780601_125_dialog_content = "Aku akan baik-baik saja. Sangat hangat...",
  ui_story_30780601_126_dialog_content = "Hangat? Ya, matahari cukup hangat hari ini...",
  ui_story_30780601_127_dialog_content = "Hehe, memang begitu...",
  ui_story_30780601_128_dialog_content = "Ini... Ini adalah ayat yang sedang aku baca sebelum aku tertidur...",
  ui_story_30780601_129_dialog_content = "Mari kita lihat di sini...",
  ui_story_30780601_130_dialog_content = "\"Angin selatan mengenal hatiku, dan membawa mimpiku ke barat.\"",
  ui_story_30780601_131_dialog_content = "Jadi... Apa artinya itu?",
  ui_story_30780601_132_dialog_content = "Jika saya harus menebak... Penulis ingin mengunjungi tempat yang jauh dalam mimpinya dan berbagi perasaannya dengan seseorang di sana... Mungkin kampung halamannya?",
  ui_story_30780601_133_dialog_content = "Kampung halaman mereka... Kampung halaman saya...",
  ui_story_30780601_134_dialog_content = "Hah? Apa itu, Robyn?",
  ui_story_30780601_135_dialog_content = "Tidak ada apa-apa... Jadi, apakah kamu bermimpi tentang sesuatu, PlayerName?",
  ui_story_30780601_136_dialog_content = "Yah... Aku bangun begitu tiba-tiba sampai-sampai aku tidak benar-benar ingat apa-apa.",
  ui_story_30780601_137_dialog_content = "Tapi tepat sebelum aku tertidur, aku melihatmu sedang membaca dengan tenang di bawah sinar matahari. Itu adalah pemandangan yang begitu tenang dan damai.",
  ui_story_30780601_138_dialog_content = "Saya cukup yakin kamu telah meneruskan rasa damai itu padaku, itulah sebabnya saya tidur begitu nyenyak barusan!",
  ui_story_30780601_139_dialog_content = "Oh, begitu…",
  ui_story_30780601_140_dialog_content = "Selain dari Dayna, aku belum pernah merasa santai seperti ini di sekitar orang lain...",
  ui_story_30780601_141_dialog_content = "Hanya saja... Sebenarnya, saya belum menjelaskan tentang buku-buku ini kepada kamu. Maaf!",
  ui_story_30780601_142_dialog_content = "Jangan. Saat kamu di sini bersamaku, aku merasa bisa lebih fokus pada membacaanku.",
  ui_story_30780601_143_dialog_content = "Sebenarnya... Ada satu jenis buku lain yang ingin saya baca bersamamu, PlayerName...",
  ui_story_30780601_144_dialog_content = "Puisi itu bagus, tetapi cenderung membuat orang mengantuk... Buku yang sedang kupikirkan seharusnya benar-benar menarik perhatian pembaca, hampir seperti sihir.",
  ui_story_30780601_145_dialog_content = "Oh? Jadi, buku macam apa mereka?",
  ui_story_30780601_146_dialog_content = "Mereka adalah cerita yang berjalan sangat cepat, jenis cerita dengan pahlawan yang sangat kuat yang menjunjung tinggi keadilan dan melawan kejahatan.",
  ui_story_30780601_147_dialog_content = "Saya mendengar para pedagang Umbraton membicarakan mereka dari waktu ke waktu...",
  ui_story_30780601_148_dialog_content = "Aku yakin mudah untuk menyukai buku seperti itu, apa kamu setuju?",
  ui_story_30780601_149_dialog_content = "Kurasa semua itu tergantung pada kualitas ceritanya.",
  ui_story_30780601_150_dialog_content = "Itu... seharusnya tidak menjadi masalah.",
  ui_story_30780601_151_dialog_content = "Ada cerita tertentu yang sedang populer di Umbraton akhir-akhir ini... Ini tentang seorang pendekar pedang legendaris. Aku sangat ingin mendapatkan salinan...",
  ui_story_30780601_152_dialog_content = "Aku tidak bisa mengingat namanya, tapi kamu bisa bilang itu langsung datang dari Longzhou... Apakah kamu tahu cerita apa yang aku bicarakan, PlayerName?",
  ui_story_30780601_153_dialog_content = "Seorang pendekar pedang legendaris... Tunggu, aku tahu yang kamu maksud! Kamu beruntung juga, karena aku tahu itu seperti telapak tangan sendiri!",
  ui_story_30780601_154_dialog_content = "Aku akan menceritakan seluruh cerita sekarang juga, jadi bersantailah!"
}
return config
